4	
5	// schedule performs the trial placement. Among nodes whose labels contain
6	// every selector pair and whose CPU and memory capacities both fit the
7	// request, it picks the name that is smallest in UTF-8 byte order. Capacity
8	// is only probed and never deducted; priority does not affect the choice.
9	// It returns the record's status together with its node and reason fields:
10	// placed with the chosen node and no reason, or rejected with no node and
11	// reason no_eligible_node. An empty candidate list rejects like any list
12	// without an eligible node.
13	func schedule(p *store.Placement) (status string, node *string, reason *string) {
14		var chosen string
15		found := false
16		for i := range p.Nodes {
17			n := &p.Nodes[i]
18			if !labelsContain(n.Labels, p.Selector) {
19				continue
20			}
21			if n.CPU < p.Resources.CPU || n.Memory < p.Resources.Memory {
22				continue
23			}
