13	
14	// acceptViaService parses a request body with the shared strict parser and
15	// then submits it through the independent business entry point.
16	func acceptViaService(t *testing.T, svc *service.Service, body string) (*store.Placement, service.Outcome) {
17		t.Helper()
18		p, err := placement.ParsePlacementInput([]byte(body))
19		if err != nil {
20			t.Fatalf("parse %q: %v", body, err)
21		}
22		rec, outcome, err := svc.Accept(t.Context(), p)
23		if err != nil {
24			t.Fatalf("accept: %v", err)
25		}
26		return rec, outcome
27	}
28	
29	func recordAsMap(t *testing.T, rec *store.Placement) map[string]any {
30		t.Helper()
31		data, err := json.Marshal(rec)
32		if err != nil {
33			t.Fatalf("marshal record: %v", err)
34		}
35		var m map[string]any
36		if err := json.Unmarshal(data, &m); err != nil {
37			t.Fatalf("unmarshal record: %v", err)
38		}
39		return m
40	}
41	
42	func expectSameRecordAsHTTP(t *testing.T, rec *store.Placement, httpBody string) {
43		t.Helper()
44		var viaHTTP map[string]any
45		if err := json.Unmarshal([]byte(httpBody), &viaHTTP); err != nil {
46			t.Fatalf("decode http body %q: %v", httpBody, err)
47		}
48		if direct := recordAsMap(t, rec); !reflect.DeepEqual(direct, viaHTTP) {
49			t.Fatalf("records differ between service entry point and HTTP response:\nservice: %v\nhttp:    %v", direct, viaHTTP)
50		}
51	}
52	
53	// expectOutcomeHTTP checks that a business acceptance outcome maps to the
54	// documented HTTP status for the same submission.
55	func expectOutcomeHTTP(t *testing.T, outcome service.Outcome, status int) {
56		t.Helper()
57		want := map[service.Outcome]int{
58			service.Created:   http.StatusCreated,
59			service.Identical: http.StatusOK,
60			service.Conflict:  http.StatusConflict,
61		}[outcome]
62		if status != want {
63			t.Fatalf("outcome %d maps to HTTP %d, got %d", outcome, want, status)
64		}
65	}
66	
67	// The same legal input must yield one record and matching acceptance results
68	// regardless of which channel handles the first and second submission.
69	func TestCrossCheckServiceAndHTTPAgreeOnCreateAndRetry(t *testing.T) {
70		t.Run("direct entry point first", func(t *testing.T) {
71			st, h := newTestRouter(t)
72			svc := service.New(st)
73	
74			directRec, directOutcome := acceptViaService(t, svc, validBody)
75			if directOutcome != service.Created {
76				t.Fatalf("first outcome = %d, want Created", directOutcome)
77			}
78			httpRetry := postPlacement(t, h, validBody)
79			if httpRetry.Code != http.StatusOK {
80				t.Fatalf("http retry = %d, want 200: %s", httpRetry.Code, httpRetry.Body.String())
81			}
82			expectOutcomeHTTP(t, service.Identical, httpRetry.Code)
83			expectSameRecordAsHTTP(t, directRec, httpRetry.Body.String())
84		})
85	
86		t.Run("http first", func(t *testing.T) {
87			st, h := newTestRouter(t)
88			svc := service.New(st)
89	
90			httpFirst := postPlacement(t, h, validBody)
91			if httpFirst.Code != http.StatusCreated {
92				t.Fatalf("http first = %d, want 201: %s", httpFirst.Code, httpFirst.Body.String())
93			}
94			directRec, directOutcome := acceptViaService(t, svc, validBody)
95			if directOutcome != service.Identical {
96				t.Fatalf("second outcome = %d, want Identical", directOutcome)
97			}
98			expectOutcomeHTTP(t, directOutcome, http.StatusOK)
99			expectSameRecordAsHTTP(t, directRec, httpFirst.Body.String())
100		})
101	}
