103	// Defaults filled on the wire (omitted selector/labels) must be recognized as
104	// the same content regardless of which channel sees which submission.
105	func TestCrossCheckDefaultedRetryAcrossChannels(t *testing.T) {
106		minimal := `{
107		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
108		  "resources": {"memory": 64, "cpu": 100},
109		  "nodes": [{"name": "n", "cpu": 200, "memory": 128}]
110		}`
111		withDefaults := `{
112		  "resources": {"cpu": 100, "memory": 64},
113		  "priority": 1, "queue": "q", "name": "job", "namespace": "ns",
114		  "selector": {},
115		  "nodes": [{"labels": {}, "memory": 128, "cpu": 200, "name": "n"}]
116		}`
117	
118		t.Run("http minimal then direct defaults", func(t *testing.T) {
119			st, h := newTestRouter(t)
120			svc := service.New(st)
121			first := postPlacement(t, h, minimal)
122			if first.Code != http.StatusCreated {
123				t.Fatalf("first = %d: %s", first.Code, first.Body.String())
124			}
125			rec, outcome := acceptViaService(t, svc, withDefaults)
126			if outcome != service.Identical {
127				t.Fatalf("outcome = %d, want Identical", outcome)
128			}
129			expectSameRecordAsHTTP(t, rec, first.Body.String())
130		})
131	
132		t.Run("direct minimal then http defaults", func(t *testing.T) {
133			st, h := newTestRouter(t)
134			svc := service.New(st)
135			rec, outcome := acceptViaService(t, svc, minimal)
136			if outcome != service.Created {
137				t.Fatalf("outcome = %d, want Created", outcome)
138			}
139			second := postPlacement(t, h, withDefaults)
140			if second.Code != http.StatusOK {
141				t.Fatalf("http retry = %d, want 200: %s", second.Code, second.Body.String())
142			}
143			expectSameRecordAsHTTP(t, rec, second.Body.String())
144		})
145	}
146	
147	// Reordering only the node array produces the same scheduling result but is a
148	// content conflict through both channels, and the original survives in GET.
149	func TestCrossCheckNodeReorderConflictAcrossChannels(t *testing.T) {
150		body := `{
151		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
152		  "resources": {"cpu": 1, "memory": 1},
153		  "nodes": [
154		    {"name": "n1", "cpu": 10, "memory": 10, "labels": {}},
155		    {"name": "n2", "cpu": 10, "memory": 10, "labels": {}}
156		  ]
157		}`
158		reordered := `{
159		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
160		  "resources": {"cpu": 1, "memory": 1},
161		  "nodes": [
162		    {"name": "n2", "cpu": 10, "memory": 10, "labels": {}},
163		    {"name": "n1", "cpu": 10, "memory": 10, "labels": {}}
164		  ]
165		}`
166	
167		st, h := newTestRouter(t)
168		svc := service.New(st)
169	
170		first := postPlacement(t, h, body)
171		if first.Code != http.StatusCreated {
172			t.Fatalf("first = %d: %s", first.Code, first.Body.String())
173		}
174		conflictRec, outcome := acceptViaService(t, svc, reordered)
175		if outcome != service.Conflict {
176			t.Fatalf("outcome = %d, want Conflict", outcome)
177		}
178		expectOutcomeHTTP(t, outcome, http.StatusConflict)
179	
180		// The independent entry point hands back the untouched original.
181		got := doRequest(t, h, http.MethodGet, "/v1/placements?namespace=ns&name=job", "")
182		if got.Code != http.StatusOK {
183			t.Fatalf("get = %d: %s", got.Code, got.Body.String())
184		}
185		expectSameRecordAsHTTP(t, conflictRec, got.Body.String())
186		if nodes := decodeBody(t, got)["nodes"].([]any); len(nodes) != 2 ||
187			nodes[0].(map[string]any)["name"] != "n1" || nodes[1].(map[string]any)["name"] != "n2" {
188			t.Fatalf("original node order changed: %s", got.Body.String())
189		}
190	
191		// The HTTP channel must reach the same verdict for the same reordering.
192		httpConflict := postPlacement(t, h, reordered)
193		expectErrorCode(t, httpConflict, http.StatusConflict, "PlacementConflictError")
194	}
195	
196	// A rejected decision produced through the independent entry point is stored
197	// and reads back through HTTP unchanged, including null node and the reason.
198	func TestCrossCheckRejectedRecordQueryableOverHTTP(t *testing.T) {
199		body := `{
200		  "namespace": "team-a", "name": "job-2", "queue": "default", "priority": -1,
201		  "resources": {"cpu": 2000, "memory": 256},
